  const n=state.echo.period==='night'?1:0,key=b[0]+':'+n;const invite=state.echo.behaviors.includes(b[0]+':0')&&state.echo.behaviors.includes(b[0]+':1')&&!state.caught.includes(b[0])?[{text:'邀请它自愿同行',fn:()=>{if(state.caught.includes(b[0])){closeModal();return}const where=catchMon(b[0],10);echoRecord(b[1]+'选择与你同行');dialog(b[1],'它认出了白天和夜里陪它观察的人，轻轻碰了一下精灵球。'+where+'。',undefined,b[0]+'-front')}}]:[];
  dialog(b[1]+' · 自然观察',b[3+n]+'。<br>白天与夜间，它会有不同的行为。',[{text:state.echo.behaviors.includes(key)?'已经记下这次观察':'记下它自己的选择',fn:()=>{if(!state.echo.behaviors.includes(key)){state.echo.behaviors.push(key);seen(b[0]);state.berries+=1;echoRecord(b[1]+'：'+b[3+n]+' · 树果 +1')}closeModal()}},...invite,{text:'暂时离开',fn:closeModal}],b[0]+'-front');
