function echoRest(){state.echo.period=state.echo.period==='night'?'day':'night';echoRecord('在街区休息至'+(state.echo.period==='night'?'夜间':'白天'));echoRefresh();closeModal();toast('现在是'+(state.echo.period==='night'?'夜间':'白天')+'，看看居民和宝可梦有什么变化。');}
function echoCases(){
 const e=state.echo,i=state.area,buttons=[],lines=[];
 if(i<4){const [name,text]=EVIDENCE[i];if(state.stage>=5){lines.push('<b>'+name+'</b><br>'+text);buttons.push({text:e.evidence.includes(i)?'旧证据已核对':'核对并保存原始证据',fn:()=>{if(!e.evidence.includes(i)){e.evidence.push(i);echoRecord('旧证据：'+name)}echoCases()}})}else lines.push('等三枚碎片共鸣后，再来核对七年前的原始记录。');}
 for(const c of CASES.filter(c=>c.area===i&&(!c.post||state.stage===6))){const n=e.cases[c.id]||0;lines.push('<b>'+c.name+'</b><br>'+(n===3?c.after:c.steps[n]));if(n<3)buttons.push({text:'跟进委托 · '+c.name,fn:()=>{const n=e.cases[c.id]||0;if(n>=3){echoCases();return}e.cases[c.id]=n+1;echoRecord(c.name+'：'+c.steps[n]);if(n===2){state.berries+=3;echoRecord(c.after+' · 树果 +3');echoRefresh()}echoCases()}});}
 buttons.push({text:'休息，切换日夜',fn:echoRest},{text:'继续探索',fn:closeModal});dialog('街区委托与旧证据',lines.join('<br><br>')||'这里没有新的委托。看看身边的伙伴，或者回事务台聊聊。',buttons);
}
