function observeRoute(e){
 const r=ROUTES[e.route],key=e.route+':'+e.point;
 const recorded=state.surveys.includes(key);
 dialog(r.notes[e.point],r.lines[e.point]+'<br><br><b>'+RELAY_CHAPTERS[e.route][0]+'</b><br>'+RELAY_CHAPTERS[e.route][1]+(recorded?'<br><br>这条发现已经记在手记里。':'<br><br>和伙伴一起把这条发现记下来。'),recorded?undefined:[{text:'记录这次发现',fn:()=>{
  if(state.surveys.includes(key)){closeModal();return}
  state.surveys.push(key);state.team[0].bond=Math.min(100,state.team[0].bond+2);
  const count=state.surveys.filter(k=>k.startsWith(e.route+':')).length;
  let reward='伙伴羁绊 +2。';
  if(count===3){state.balls+=3;state.berries+=3;state.money+=180;reward+=' 完成本条路线观察：精灵球 ×3、树果 ×3、旅费 ₽180。'}
  save();sync();dialog('旅行手记 · '+r.name,`已记录 ${count}/3。${reward}`,undefined,r.npc);
 }},{text:'先继续探索',fn:closeModal}],r.npc);
}

function relayReport(){
 if(state.relayReported){dialog('大木博士 · 新的路图','六封回信已经收好。我们会在每个岔路口挂上新的路牌，让下一位旅人知道，他的声音总有人听见。');return}
 dialog('最后一封回信，寄给明天','博士把六条路的记录铺开：风铃送出消息，草原护送生命，山路传递灯光，古道留下求救，海岸接人回家，山庭迎接明天。<br><br>“核心修好了，只是让声音能传过去。你们走完这些路，才让声音有了愿意回答的人。”',[{text:'把路图留给下一位旅人',fn:()=>{if(!state.relayReported){state.relayReported=true;state.coins+=60;save();sync()}dialog('森屿回响 · 路的另一端','博士把你的记录放在研究所门口。奖励：60 枚代币。故事没有被锁进遗迹，它留在每一条还有人经过的路上。')}}]);
}

